import re

def parse_duration(s: str) -> int:
    total = 0
    # Match optional hours, minutes, and seconds in order
    match = re.fullmatch(r'(\d+h)?(\d+m)?(\d+s)?', s)
    if match:
        if match.group(1):
            total += int(match.group(1)[:-1]) * 3600
        if match.group(2):
            total += int(match.group(2)[:-1]) * 60
        if match.group(3):
            total += int(match.group(3)[:-1])
    return total
