def evaluate(expr: str) -> int:
    # Remove all spaces for easier parsing
    s = expr.replace(' ', '')
    n = len(s)
    pos = [0]  # mutable index to allow inner functions to modify it

    def parse_expression() -> int:
        """Handle addition and subtraction."""
        left = parse_term()
        while pos[0] < n and s[pos[0]] in '+-':
            op = s[pos[0]]
            pos[0] += 1
            right = parse_term()
            if op == '+':
                left += right
            else:
                left -= right
        return left

    def parse_term() -> int:
        """Handle multiplication and division."""
        left = parse_factor()
        while pos[0] < n and s[pos[0]] in '*/':
            op = s[pos[0]]
            pos[0] += 1
            right = parse_factor()
            if op == '*':
                left *= right
            else:
                # integer division truncating toward zero
                left = int(left / right)
        return left

    def parse_factor() -> int:
        """Handle parentheses and numbers."""
        if s[pos[0]] == '(':
            pos[0] += 1  # skip '('
            val = parse_expression()
            pos[0] += 1  # skip ')'
            return val
        else:
            # parse a non-negative integer
            start = pos[0]
            while pos[0] < n and s[pos[0]].isdigit():
                pos[0] += 1
            return int(s[start:pos[0]])

    return parse_expression()
