import re

def calc(expr: str) -> int:
    # Remove all spaces
    s = expr.replace(' ', '')
    n = len(s)
    pos = [0]  # mutable index for nested functions

    def peek():
        return s[pos[0]] if pos[0] < n else ''

    def consume():
        ch = s[pos[0]]
        pos[0] += 1
        return ch

    # parse_primary: number or '(' expr ')'
    def parse_primary():
        if peek() == '(':
            consume()  # '('
            val = parse_expr()
            # expect ')'
            if peek() == ')':
                consume()
            return val
        # parse integer (non-negative)
        start = pos[0]
        while pos[0] < n and s[pos[0]].isdigit():
            pos[0] += 1
        return int(s[start:pos[0]])

    # parse_unary: handles unary minus
    def parse_unary():
        if peek() == '-':
            consume()
            return -parse_unary()
        return parse_primary()

    # parse_power: exponentiation, right-associative
    def parse_power():
        left = parse_unary()
        if peek() == '^':
            consume()
            right = parse_power()  # right-associative: parse right recursively
            # exponentiation, result is non-negative integer
            left = left ** right
        return left

    # parse_term: * and / (left-associative)
    def parse_term():
        left = parse_power()
        while True:
            op = peek()
            if op == '*' or op == '/':
                consume()
                right = parse_power()
                if op == '*':
                    left = left * right
                else:
                    # integer division truncating toward zero
                    # Python's // truncates toward negative infinity,
                    # so we use int(a / b) which truncates toward zero.
                    left = int(left / right)
            else:
                break
        return left

    # parse_expr: + and - (left-associative)
    def parse_expr():
        left = parse_term()
        while True:
            op = peek()
            if op == '+' or op == '-':
                consume()
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    result = parse_expr()
    return result
