def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def two_digits(num: int) -> str:
        if num < 10:
            return ones[num]
        if num < 20:
            return teens[num - 10]
        t = num // 10
        o = num % 10
        if o == 0:
            return tens[t]
        return tens[t] + "-" + ones[o]

    def three_digits(num: int) -> str:
        if num == 0:
            return ""
        h = num // 100
        r = num % 100
        parts = []
        if h > 0:
            parts.append(ones[h] + " hundred")
        if r > 0:
            parts.append(two_digits(r))
        return " ".join(parts)

    # Process groups: millions, thousands, ones
    millions = n // 1_000_000
    remainder = n % 1_000_000
    thousands = remainder // 1_000
    ones_part = remainder % 1_000

    result = []

    if millions > 0:
        result.append(ones[millions] + " million")
    if thousands > 0:
        result.append(three_digits(thousands) + " thousand")
    if ones_part > 0:
        result.append(three_digits(ones_part))

    return " ".join(result)
