def flatten_json(obj: dict) -> dict:
    result = {}

    def _flatten(current, path):
        if isinstance(current, dict):
            if not current:
                result['.'.join(path)] = current
            else:
                for k, v in current.items():
                    _flatten(v, path + [k])
        elif isinstance(current, list):
            if not current:
                result['.'.join(path)] = current
            else:
                for i, v in enumerate(current):
                    _flatten(v, path + [str(i)])
        else:
            result['.'.join(path)] = current

    _flatten(obj, [])
    return result
